import{_ as a,o as i,c as o,at as t}from"./chunks/framework.CY22Hent.js";const e="/assets/ruankao_20241024183343.B-ENk8vQ.png",p="/assets/ruankao_20241024183435.D1uKRW8I.png",r="/assets/ruankao_20241024183513.BgDneudi.png",n="/assets/ruankao_20241024183631.BApYdqa8.png",s="/assets/ruankao_20241024183750.CeH0ofZC.png",u="/assets/ruankao_20241024183837.EbLpKlWf.png",_="/assets/ruankao_20241024183910.DgSsAXMz.png",f=JSON.parse('{"title":"软件设计师笔记12_软件系统分析与设计","description":"","frontmatter":{"title":"软件设计师笔记12_软件系统分析与设计","date":"2025-04-05T00:00:00.000Z","lastUpdated":"2025-11-06T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/软件设计师笔记12_软件系统分析与设计.md","filePath":"blogs/软考/软件设计师笔记12_软件系统分析与设计.md"}'),c={name:"blogs/软考/软件设计师笔记12_软件系统分析与设计.md"};function d(h,l,k,b,q,g){return i(),o("div",null,[...l[0]||(l[0]=[t('<p>[toc]</p><h1 id="软件设计师笔记12-软件系统分析与设计" tabindex="-1">软件设计师笔记12_软件系统分析与设计 <a class="header-anchor" href="#软件设计师笔记12-软件系统分析与设计" aria-label="Permalink to &quot;软件设计师笔记12_软件系统分析与设计&quot;">​</a></h1><p>下面的内容参考自《软件设计师教程(第5版)》 这本书的第12章 软件系统分析与设计。</p><p>软件设计师考试结合了当前软件设计开发中的主流技术和工程应用背景，强调了主流设计技术的应用问题，读者除应掌握基本的概念和理论基础知识外，还需要正确地针对实践应用中的问题提出合理的解决方案，将一系列的设计方法与原则应用在实际系统的分析、设计和开发环节中。</p><p>编者委员会总结近几年的软件设计师考试所涉及的应用性内容，将其主要技术领域归纳为以下几点。</p><ul><li>(1)结构化分析与设计。</li><li>(2)数据库分析与设计。</li><li>(3)面向对象分析与设计。</li><li>(4)算法设计与C程序实现。</li><li>(5)面向对象的程序设计与实现。</li></ul><h2 id="结构化分析与设计" tabindex="-1">结构化分析与设计 <a class="header-anchor" href="#结构化分析与设计" aria-label="Permalink to &quot;结构化分析与设计&quot;">​</a></h2><p>结构化分析是将数据和处理(加工)作为分析对象，数据的分析结果表示了现实世界中实体的属性及其之间的相互关系，而处理的分析结果则展现了系统对数据的加工和转换。</p><p>面向数据流建模是目前仍然被广泛使用的方法之一，而DFD则是面向数据流建模中的重要工具。</p><p>DFD将系统建模成输入-处理一输出的模型，即流入软件的数据对象，经由处理的转换，最后以结果数据对象的形式流出软件。</p><blockquote><p>对问题进行结构化分析，其实施步骤如下。</p></blockquote><ul><li>(1)确定系统边界，画出系统环境图。</li><li>(2)自顶向下画出各层数据流图。</li><li>(3)定义数据字典。</li><li>(4)定义加工说明。</li><li>(5)将图、字典以及加工组成分析模型。</li></ul><blockquote><p>在实际使用DFD进行数据流建模时，需要注意以下原则。</p></blockquote><ul><li>(1)加工和数据流的正确使用。如一个加工必须既有输入又有输出;数据流只能和加工相关，即从加工流向加工、数据源流向加工或加工流向数据源。</li><li>(2)每个数据流和数据存储都要在数据字典中有定义，数据字典包括各层数据流图中数据元素的定义。</li><li>(3)数据流图中最底层的加工必须有加工说明。</li><li>(4)父图和子图必须平衡。即父图中某加工的输入/输出(数据流)和分解这个加工的子图的输入/输出数据流必须完全一致。</li><li>(5)加工处理说明和数据流图中加工涉及的元素保持一致。例如，在加工处理说明中，输入数据流必须说明其如何使用，输出数据流说明如何产生或选取，数据存储说明如何选取、使用或修改。</li><li>(6)一幅图中的图元个数控制在7±2 以内。</li></ul><blockquote><p>总结</p></blockquote><ul><li>结构化分析的对象包括数据（实体对象的属性和关系）和处理（对信息的加工和处理）。</li><li>数据流图（DFD）是面向数据流建模的工具。</li><li>进行结构化分析的步骤：①确定系统边界，绘制系统环境图；②绘制各层数据流图（自顶向下）；③定义数据字典；④定义加工（处理）说明；⑤将图、字典和加工组成分析模型。</li><li>系统总体设计模型反映模块间的调用关系，可以采用层次图、HIPO 图和机构图进行表达。</li><li>数据流图分为变换型数据流图和事务型数据流图。事务型数据流图的处理为条件判断式，根据不同输入数据的类型对应不同的处理动作。</li><li>详细设计可以采用程序流程图、N-S 图、PAS 图和 PDL 语言等工具进行表达。</li><li>结构化分析的最终结果：数据流图、数据字典和加工处理说明。</li></ul><h2 id="数据库分析与设计" tabindex="-1">数据库分析与设计 <a class="header-anchor" href="#数据库分析与设计" aria-label="Permalink to &quot;数据库分析与设计&quot;">​</a></h2><h3 id="数据库设计的策略" tabindex="-1">数据库设计的策略 <a class="header-anchor" href="#数据库设计的策略" aria-label="Permalink to &quot;数据库设计的策略&quot;">​</a></h3><p>数据库设计的一般策略有两种:自顶向下(Top Down)和自底向上(Bottom Up)。</p><ul><li>自顶向下是从一般到特殊的开发策略。它是从一个企业的高层管理着手，分析企业的目标、对象和策略，构造抽象的高层数据模型。然后逐步构造越来越详细的描述和模型(子系统的模型)。模型不断地扩展细化，直到能识别特定的数据库及其应用为止。</li><li>自底向上的开发采用与抽象相反的顺序进行。它从各种基本业务和数据处理着手，即从一个企业的各个基层业务子系统的业务处理开始，进行分析和设计。然后将各子系统进行综合和集中，进行上一层系统的分析和设计，将不同的数据进行综合。最后得到整个信息系统的分析和设计。</li></ul><p>这两种方法各有优缺点。在实际的数据库设计开发过程中，常常把这两种方法综合起来使用。</p><h3 id="数据库设计的步骤" tabindex="-1">数据库设计的步骤 <a class="header-anchor" href="#数据库设计的步骤" aria-label="Permalink to &quot;数据库设计的步骤&quot;">​</a></h3><p>数据库应用系统的生命周期分为六个阶段：数据库规划、需求描述与分析、数据库设计与应用程序设计、实现、测试、运行与维护。</p><p>其中：</p><ul><li>需求描述与分析是以用户的角度进行的。</li><li>应用程序设计包括事务设计和用户界面设计。</li><li>DDL（数据定义语言）用于建立数据库。</li></ul><h4 id="数据库设计的四个主要阶段" tabindex="-1">数据库设计的四个主要阶段 <a class="header-anchor" href="#数据库设计的四个主要阶段" aria-label="Permalink to &quot;数据库设计的四个主要阶段&quot;">​</a></h4><p>数据库设计的四个主要阶段有：用户需求分析、概念结构设计、逻辑结构设计、物理结构设计。</p><blockquote><p>用户需求分析。</p></blockquote><p>在需求调研的过程中，需要获得用户对系统的要求包括信息要求（保存哪些数据）、处理要求（实现什么功能）、系统要求（安全要求等）。</p><blockquote><p>概念结构设计。</p></blockquote><p>概念设计中概念模型的理想工具是 E-R 图，由实体、属性和实体间的联系三要素组成</p><ul><li>1）概念结构设计的目标是产生反映系统信息需求的数据库概念结构，即概念模型。</li><li>2）概念结构设计的策略通常有以下四种：自顶向下、自底向上、逐步扩张和混合策略。</li></ul><p>概念结构设计的工作步骤如图所示。 <img src="'+e+'" alt="ruankao_20241024183343.png" loading="lazy"></p><blockquote><p>逻辑结构设计。</p></blockquote><p>逻辑结构设计包括模式初始设计、子模式设计、应用程序设计、模式评价、模式求精。逻辑结构设计即是在概念结构设计的基础上进行数据模型设计，可以分为层次模型、网状模型和关系模型。</p><p>逻辑结构设计的工作步骤如图所示。 <img src="'+p+'" alt="ruankao_20241024183435.png" loading="lazy"></p><blockquote><p>数据库的物理设计</p></blockquote><p>物理设计包括确定数据分布、存储结构和访问方式。综合考虑提高数据的访问速度，本阶段需要确定数据库文件的索引字段和索引类型。数据库的物理结构主要由存储记录格式、记录在物理设备上的安排及访问路径（存取方法）构成。</p><p>数据库物理设计的工作步骤如图所示。 <img src="'+r+'" alt="ruankao_20241024183513.png" loading="lazy"></p><blockquote><p>数据库的实施与维护</p></blockquote><p>数据库实施阶段的工作步骤如图所示。 <img src="'+n+'" alt="ruankao_20241024183631.png" loading="lazy"></p><h2 id="面向对象分析与设计" tabindex="-1">面向对象分析与设计 <a class="header-anchor" href="#面向对象分析与设计" aria-label="Permalink to &quot;面向对象分析与设计&quot;">​</a></h2><blockquote><p>面向对象分析与设计的步骤</p></blockquote><ul><li>面向对象分析包括四个活动：建模系统功能、定义领域模型、定义交互行为和状态、定义设计类图。</li><li>通过用例建模系统功能的步骤：①确定参与者；②确定需求用例；③构造用例模型；④记录需求用例描述。</li></ul><blockquote><p>建模对象状态</p></blockquote><p>建模状态图应遵循的指导原则如下：①状态名称简单但具有描述性；②避免黑洞（有进无出）；③避免奇迹（有出无进）；④符合状态需对子状态集进行建模；⑤为复杂的实体创建分层的状态图</p><h2 id="算法分析与设计" tabindex="-1">算法分析与设计 <a class="header-anchor" href="#算法分析与设计" aria-label="Permalink to &quot;算法分析与设计&quot;">​</a></h2><p>算法设计的主要步骤如图所示。 <img src="'+s+'" alt="ruankao_20241024183750.png" loading="lazy"></p><p>算法问题类型如表所示。 <img src="'+u+'" alt="ruankao_20241024183837.png" loading="lazy"></p><p>现代优化计算方法如图所示 <img src="'+_+'" alt="ruankao_20241024183910.png" loading="lazy"></p><h2 id="面向过程的程序设计与实现" tabindex="-1">面向过程的程序设计与实现 <a class="header-anchor" href="#面向过程的程序设计与实现" aria-label="Permalink to &quot;面向过程的程序设计与实现&quot;">​</a></h2><ul><li>变量的本质是程序中用来存放数据的一段存储空间，通常其对应的存储空间为内存区域。</li><li>变量具有类型、值、地址、作用域和生存期等属性。</li><li>存储变量地址的变量称为指针变量。</li><li>当一个指针变量指向仍为指针变量时，称为多级变量，级数越多，数据访问效率越低</li></ul><h2 id="面向对象的程序设计与实现" tabindex="-1">面向对象的程序设计与实现 <a class="header-anchor" href="#面向对象的程序设计与实现" aria-label="Permalink to &quot;面向对象的程序设计与实现&quot;">​</a></h2><p>当设计与实现面向对象的程序时，需要注意以下四点：</p><ul><li>能够根据设计模式的名称画出其对应的类图。</li><li>理解类图中每一个类的作用与功能。</li><li>能够将现实问题中所描述的各种职责映射到类图中具体的类。</li><li>能够使用一种面向对象语言实现设计</li></ul>',55)])])}const D=a(c,[["render",d]]);export{f as __pageData,D as default};
